// 03 - ICMP & Counters: gateway echo rounds and the GENET DMA counters.
// One suite, one file: it registers itself with the runner; there is no
// list of suites to keep in step with the files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>
#include "eth_helpers.hpp"

using namespace os::rtos;
using namespace mtp_eth;

// 03 - ICMP & Counters
// ===========================================================================
mt::static_suite suite_icmp_counters{
  "03 - ICMP & Counters", mtp_board::runner (),
  [] (mt::suite& ts) {
    ts.test ("gateway answers 56-byte ICMP echo requests", [] (auto& t) {
      unsigned replies = 0;
      if (g_up.address)
        {
          app::serve_for (50);
          const char* gateway
              = ETH_TEST_GATEWAY[0] != '\0' ? ETH_TEST_GATEWAY : "gw";
          replies = net::ping (gateway, 4, 56);
          app::log ("ping gateway (56 B): %u of 4 replies\n", replies);
        }
      std::printf ("# ICMP echo (56 B payload): %u / 4 replies\n", replies);
      t.expect (mt::gt (replies, 0u))
          << fmt ("%u of 4 ICMP echo replies (56 B)", replies);
    });

    ts.test ("gateway answers 256-byte ICMP echo requests", [] (auto& t) {
      unsigned replies = 0;
      if (g_up.address)
        {
          const char* gateway
              = ETH_TEST_GATEWAY[0] != '\0' ? ETH_TEST_GATEWAY : "gw";
          replies = net::ping (gateway, 2, 256);
          app::log ("ping gateway (256 B): %u of 2 replies\n", replies);
          if (ETH_TEST_PEER[0] != '\0')
            {
              const unsigned peer = net::ping (ETH_TEST_PEER, 2, 56);
              app::log ("ping %s: %u of 2 replies\n", ETH_TEST_PEER, peer);
            }
        }
      std::printf ("# ICMP echo (256 B payload): %u / 2 replies\n", replies);
      t.expect (mt::gt (replies, 0u))
          << fmt ("%u of 2 ICMP echo replies (256 B)", replies);
    });

    ts.test ("GENET v5 DMA TX and RX rings report error-free frame traffic",
             [] (auto& t) {
               const auto& st = genet::stats ();
               app::log ("frames: rx %u (%u errors), tx %u (%u errors)\n",
                         static_cast<unsigned> (st.rx_frames),
                         static_cast<unsigned> (st.rx_errors),
                         static_cast<unsigned> (st.tx_frames),
                         static_cast<unsigned> (st.tx_errors));
               std::printf (
                   "# frames: rx %u (%u errors), tx %u (%u errors), %u link "
                   "change(s)\n",
                   static_cast<unsigned> (st.rx_frames),
                   static_cast<unsigned> (st.rx_errors),
                   static_cast<unsigned> (st.tx_frames),
                   static_cast<unsigned> (st.tx_errors),
                   static_cast<unsigned> (st.link_changes));
               t.expect (mt::ge (st.tx_frames, 6u))
                   << fmt ("TX DMA ring sent %u frames", st.tx_frames);
               t.expect (mt::ge (st.rx_frames, 6u))
                   << fmt ("RX DMA ring received %u frames", st.rx_frames);
               t.expect (mt::eq (st.tx_errors, 0u)) << "0 TX DMA errors";
               t.expect (mt::eq (st.rx_errors, 0u)) << "0 RX DMA errors";
             });
  }
};
